using System.IO;using System.Text.Json;using System.Windows.Controls;namespace LSBROWSER_CLEAN{    public partial class SettingsPage : UserControl    {        private readonly string settingsPath = "settings.json";        public SettingsPage()        {            InitializeComponent();            LayoutSelector.SelectionChanged += LayoutSelector_SelectionChanged;        }        private void LayoutSelector_SelectionChanged(object sender, string mode)        {            var json = new { layout = mode };            File.WriteAllText(settingsPath, JsonSerializer.Serialize(json));        }    }}